using System;
namespace LWS.TruckDentist {
 public enum DentalToolKind { Brush,Drill,Extractor,Air,Water,Cleaner }
 public enum DentalTask { Dirty,Cavity,Loose,Healthy }
 [Serializable]public sealed class DentalRules {
  public const int TeethPerOwner=4;public readonly int[] points=new int[4],procedures=new int[4],mistakes=new int[4],stage=new int[16];public readonly float[] work=new float[16];public readonly bool[] done=new bool[16],broken=new bool[16];readonly float[,] nextMistake=new float[16,4];
  public int Count{get;private set;}public int Round{get;private set;}public int Rounds{get;private set;}public float Clock{get;private set;}public float RoundSeconds{get;private set;}public float ReadySeconds{get;private set;}public bool Complete{get;private set;}public bool Active=>!Complete&&ReadySeconds<=0;float completedAt=-1;
  public static DentalTask Task(int tooth)=>(DentalTask)(tooth%4);public static float Required(DentalToolKind tool)=>tool==DentalToolKind.Brush?2:tool==DentalToolKind.Drill?1.7f:tool==DentalToolKind.Cleaner?1.2f:.75f;
  public void Reset(int count,int rounds){Count=Math.Clamp(count,1,4);Rounds=Math.Clamp(rounds,1,7);Round=0;Clock=0;Complete=false;Array.Clear(points,0,4);Array.Clear(procedures,0,4);Array.Clear(mistakes,0,4);ResetRound();}
  void ResetRound(){Array.Clear(stage,0,16);Array.Clear(work,0,16);Array.Clear(done,0,16);Array.Clear(broken,0,16);Array.Clear(nextMistake,0,nextMistake.Length);ReadySeconds=3;RoundSeconds=180;completedAt=-1;}
  public void Tick(float dt){if(Complete||!float.IsFinite(dt)||dt<=0)return;dt=Math.Min(dt,.1f);Clock+=dt;if(ReadySeconds>0){ReadySeconds=Math.Max(0,ReadySeconds-dt);return;}RoundSeconds=Math.Max(0,RoundSeconds-dt);bool all=true;for(int s=0;s<Count;s++)for(int k=0;k<3;k++)all&=done[s*4+k];if(all&&completedAt<0)completedAt=Clock;if(RoundSeconds<=0||completedAt>=0&&Clock-completedAt>=4){if(Round+1>=Rounds)Complete=true;else{Round++;ResetRound();}}}
  bool Valid(int round,int id,int slot)=>Active&&round==Round&&id>=0&&id<Count*4&&slot>=0&&slot<Count;
  public int Expected(int id){if(id<0||id>=Count*4||done[id]||Task(id)==DentalTask.Healthy)return -1;int s=stage[id];if(Task(id)==DentalTask.Dirty)return s==0?(int)DentalToolKind.Water:s==1?(int)DentalToolKind.Brush:s==2?(int)DentalToolKind.Cleaner:(int)DentalToolKind.Air;if(Task(id)==DentalTask.Cavity)return s==0||s==2?(int)DentalToolKind.Water:s==1?(int)DentalToolKind.Drill:s==3?(int)DentalToolKind.Cleaner:(int)DentalToolKind.Air;return s==0?(int)DentalToolKind.Water:(int)DentalToolKind.Extractor;}
  int Mistake(int id,int slot,int amount){if(Clock<nextMistake[id,slot])return 0;nextMistake[id,slot]=Clock+1;mistakes[slot]++;points[slot]-=amount;return -amount;}
  public int Contact(int round,int id,int slot,DentalToolKind tool,float dt,float actualTipSpeed,float nativeForce){if(!Valid(round,id,slot)||!float.IsFinite(dt)||!float.IsFinite(actualTipSpeed)||!float.IsFinite(nativeForce)||dt<=0||(int)tool<0||(int)tool>5)return 0;if(actualTipSpeed>2.8f||nativeForce>18000)return Mistake(id,slot,15);int expected=Expected(id);if(id/4!=slot||expected!=(int)tool){if(tool==DentalToolKind.Drill||tool==DentalToolKind.Extractor||tool==DentalToolKind.Cleaner)return Mistake(id,slot,20);return 0;}if(tool==DentalToolKind.Extractor)return 0;if(actualTipSpeed>1.5f)return 0;work[id]+=Math.Min(dt,.1f);if(work[id]<Required(tool))return 0;work[id]=0;stage[id]++;int last=Task(id)==DentalTask.Dirty?4:Task(id)==DentalTask.Cavity?5:2;int award=tool==DentalToolKind.Drill?30:tool==DentalToolKind.Brush||tool==DentalToolKind.Cleaner?20:tool==DentalToolKind.Air?30:10;if(stage[id]>=last){done[id]=true;procedures[slot]++;}points[slot]+=award;return award;}
  public int SocketBroke(int round,int id,int slot,bool actualExtractorGrip){if(!Valid(round,id,slot)||done[id])return 0;if(actualExtractorGrip&&id/4==slot&&Task(id)==DentalTask.Loose&&stage[id]==1){done[id]=true;stage[id]=2;procedures[slot]++;points[slot]+=90;return 90;}broken[id]=done[id]=true;return Mistake(id,slot,60);}
  public void Broken(int round,int id){if(!Active||round!=Round||id<0||id>=Count*4)return;broken[id]=done[id]=true;}
  public int Place(int slot){int p=1;for(int i=0;i<Count;i++)if(points[i]>points[slot])p++;return p;}
 }
}
